import{_ as n,o as a,c as s,a2 as o}from"./chunks/framework.iWwp2X7T.js";const u=JSON.parse('{"title":"CLI commands","description":"Mobile Inspector development documentation · CLI commands","frontmatter":{"title":"CLI commands","description":"Mobile Inspector development documentation · CLI commands"},"headers":[],"relativePath":"en/reference/cli.md","filePath":"en/reference/cli.md"}'),t={name:"en/reference/cli.md"};function r(i,e,c,l,p,d){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="cli-commands" tabindex="-1">CLI commands <a class="header-anchor" href="#cli-commands" aria-label="Permalink to &quot;CLI commands&quot;">​</a></h1><p>Use the checkout entry <code>node bin/mobile-inspector.mjs</code> when no executable is installed on PATH. All examples use placeholder selectors obtained from your own running owner; they are not literal IDs.</p><h2 id="current-command-inventory" tabindex="-1">Current command inventory <a class="header-anchor" href="#current-command-inventory" aria-label="Permalink to &quot;Current command inventory&quot;">​</a></h2><p>Version 0.1.0 · development</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Mobile Inspector 0.1.0</span></span>
<span class="line"><span>Usage: mobile-inspector &lt;command&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  help                 Show available commands</span></span>
<span class="line"><span>  --version            Show installed version</span></span>
<span class="line"><span>  doctor [--json]      Check local prerequisites and capabilities</span></span>
<span class="line"><span>  start [server flags] Start or reuse the managed local viewer</span></span>
<span class="line"><span>  instance status      Inspect the active owner</span></span>
<span class="line"><span>  project              Register, list or configure local projects</span></span>
<span class="line"><span>  demo --project ID    Create a labelled synthetic recording</span></span>
<span class="line"><span>  query TOOL --project ID  Read scoped capture summaries</span></span>
<span class="line"><span>  incidents            Browse bounded incident evidence</span></span>
<span class="line"><span>  watch --project ID   Foreground diagnosis lease; --off stops it</span></span>
<span class="line"><span>  diagnose --project ID --incident ID --generation GEN</span></span>
<span class="line"><span>  mcp serve/setup/remove   Project-scoped evidence bridge and Codex setup</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Run start --help for connection and certificate options.</span></span></code></pre></div><h2 id="read-before-mutating" tabindex="-1">Read before mutating <a class="header-anchor" href="#read-before-mutating" aria-label="Permalink to &quot;Read before mutating&quot;">​</a></h2><p>Help and version paths do not start a collector. <code>doctor --json</code> distinguishes discovered prerequisites from operational capabilities. Start the foreground owner explicitly before project mutations, demo, queries or MCP operations. All commands accept <code>--home PATH</code>; use the same tool-owned home for one instance.</p><p><code>project add</code> grants a selected trusted Git root local project authority. <code>project build</code> maps app/platform/environment/build to an existing commit and contained source root. App-reported paths do not grant access. <code>demo --project ID</code> creates host-labelled synthetic records without business requests.</p><h2 id="query-selectors" tabindex="-1">Query selectors <a class="header-anchor" href="#query-selectors" aria-label="Permalink to &quot;Query selectors&quot;">​</a></h2><p>Call <code>query list_sessions --project ID</code>, then retain session ID and generation for trace/log requests. Default limit is 50, maximum 200. Continue <code>nextCursor</code> only with unchanged scope/selectors/limit. Stale generations and cursors fail; do not silently restart in another recording. Summary is default, and partial results expose gaps.</p><p><code>watch</code> and <code>diagnose</code> are explicit foreground orchestration commands, not guarantees of model availability. Review <a href="./diagnosis">diagnosis limitations</a>. Stop your own foreground process with Ctrl+C; never kill an arbitrary PID based on a port or stale lock.</p>`,11)])])}const h=n(t,[["render",r]]);export{u as __pageData,h as default};
